// Cincuenta peticiones y ninguna respuesta a «¿va bien el servicio?».
// Paso 1: cuenta cuántas fueron y cuántas fallaron.

const peticiones = require('./peticiones');
const { log } = require('./log');

log('info', 'arranque', { peticiones: peticiones.length });

// El mismo logger de siempre.

function log(level, event, datos) {
  console.log(
    JSON.stringify({
      ts: new Date().toISOString(),
      service: 'pedidos-api',
      level: level,
      event: event,
      ...datos,
    }),
  );
}

module.exports = { log };

