const peticiones = require('./peticiones');
const { log } = require('./log');

function percentil(valores, p) {
  const ordenados = [...valores].sort((a, b) => a - b);
  const indice = Math.ceil((p / 100) * ordenados.length) - 1;
  return ordenados[indice];
}

const total = peticiones.length;
const errores = peticiones.filter((p) => p.status >= 500).length;
const duraciones = peticiones.map((p) => p.ms);
const media = Math.round(duraciones.reduce((a, b) => a + b, 0) / duraciones.length);

log('info', 'metricas_peticiones', {
  total: total,
  errores: errores,
  porcentajeError: Math.round((errores / total) * 100),
});

log('info', 'metricas_latencia', {
  media: media,
  p50: percentil(duraciones, 50),
  p95: percentil(duraciones, 95),
  p99: percentil(duraciones, 99),
});

